const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const cinema=$("#cinema"), screen=$("#screen"), fx=$("#fx"), ctx=fx.getContext("2d");
const views=$$(".view"), answersEl=$("#answers"), livesEl=$$(".life");
const difficultyLabels={easy:"Lehká",medium:"Střední",hard:"Těžká"};
const genreLabels={comedy:"Komedie",fantasy:"Fantasy",scifi:"Sci-fi",horror:"Horor",crime:"Krimi a thriller",animation:"Animace"};
