let audioCtx=null,masterGain=null,musicGain=null,sfxGain=null,musicTimer=null,musicTheme="silent",musicStep=0,musicNextTime=0,musicGeneration=0,particles=[],raf=0,creditsEndTimer=null;

function showView(id){
  views.forEach(v=>v.classList.toggle("active",v.id===id));
}
function resizeCanvas(){
  const r=screen.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);
  fx.width=Math.max(1,Math.round(r.width*d));fx.height=Math.max(1,Math.round(r.height*d));
  fx.style.width=r.width+"px";fx.style.height=r.height+"px";ctx.setTransform(d,0,0,d,0,0);
}
addEventListener("resize",resizeCanvas,{passive:true});resizeCanvas();

function setupScene(){
  const seats=$("#seats");for(let i=0;i<12;i++)seats.insertAdjacentHTML("beforeend",'<i class="seat"></i>');
  const dust=$("#dust");for(let i=0;i<42;i++){const d=document.createElement("i");d.style.left=(8+Math.random()*84)+"%";d.style.top=(16+Math.random()*68)+"%";d.style.animationDelay=(-Math.random()*8)+"s";d.style.animationDuration=(6+Math.random()*8)+"s";dust.appendChild(d)}
  $("#bigAward").innerHTML=$("#awardSvg").innerHTML;
}
setupScene();

function openCurtain(){
  cinema.classList.add("running");
  requestAnimationFrame(()=>cinema.classList.add("open"));
  sound("projector");
}
$("#helpBtn").addEventListener("click",e=>{
  e.stopPropagation();const on=!$("#tooltip").classList.contains("show");
  $("#tooltip").classList.toggle("show",on);$("#helpBtn").setAttribute("aria-expanded",String(on));
});
screen.addEventListener("click",e=>{if(!e.target.closest(".help")&&!e.target.closest(".tooltip")){$("#tooltip").classList.remove("show");$("#helpBtn").setAttribute("aria-expanded","false")}});
$("#startBtn").addEventListener("click",()=>{
  initAudio();switchMusic("menu");openCurtain();setTimeout(()=>{showView("difficulty");screen.removeAttribute("data-genre");sound("soft")},820);
});
$$(".difficulty-card").forEach(b=>b.addEventListener("click",()=>{
  state.difficulty=b.dataset.difficulty;$("#selectedDifficulty").textContent=difficultyLabels[state.difficulty];showView("genres");sound("soft");
}));
$$(".genre-card").forEach(b=>b.addEventListener("click",()=>startGame(b.dataset.genre)));
$("#difficultyBack").addEventListener("click",()=>{showView("difficulty");sound("soft")});
$("#homeBtn").addEventListener("click",()=>{state.locked=true;resetLives(false);screen.removeAttribute("data-genre");showView("difficulty");switchMusic("menu");sound("soft")});
$("#muteBtn").addEventListener("click",()=>{
  initAudio();state.muted=!state.muted;$("#muteBtn").classList.toggle("muted",state.muted);$("#muteBtn").setAttribute("aria-label",state.muted?"Zapnout zvuk":"Vypnout zvuk");
  if(masterGain)masterGain.gain.setTargetAtTime(state.muted?0:.96,audioCtx.currentTime,.05);
  if(!state.muted&&audioCtx.state==="suspended")audioCtx.resume();
});
$("#replayEnd").addEventListener("click",resetToSelections);$("#replayWin").addEventListener("click",resetToSelections);
$("#creditsSkip").addEventListener("click",()=>{
  if(creditsEndTimer){clearTimeout(creditsEndTimer);creditsEndTimer=null}
  resetToSelections();
});
addEventListener("keydown",e=>{if($("#game").classList.contains("active")&&/[1-4]/.test(e.key)){const b=$$(".answer")[+e.key-1];if(b)b.click()}});

function clearRoundSoundFlags(){
  livesEl.forEach(x=>{delete x.dataset.mqBurnSound});
  [$("#creditsView"),$("#endView"),$("#winView")].forEach(x=>{
    if(!x)return;
    delete x.dataset.mqLoseSound;
    delete x.dataset.mqWinSound;
  });
}
function resetToSelections(){
  if(creditsEndTimer){clearTimeout(creditsEndTimer);creditsEndTimer=null}
  cinema.classList.remove("dim");$("#endCard").classList.remove("reveal");$("#winCard").classList.remove("reveal");
  const roll=$("#creditsRoll");if(roll)roll.style.animation="none";
  clearRoundSoundFlags();resetLives(false);screen.removeAttribute("data-genre");showView("difficulty");switchMusic("menu");sound("soft");
}
function resetLives(show=false){
  state.lives=3;
  livesEl.forEach(x=>{x.className="life";delete x.dataset.mqBurnSound});
  $("#filmLives").style.display=show?"grid":"none";
}

function startGame(genre){
  if(creditsEndTimer){clearTimeout(creditsEndTimer);creditsEndTimer=null}
  clearRoundSoundFlags();
  state={...state,genre,score:0,lives:3,questionNo:1,locked:false,seen:new Set(),askedQuestions:new Set(),current:null};
  $("#score").textContent="0";$("#questionNo").textContent="1";$("#progress").style.width="0%";
  $("#themeLabel").textContent=`${difficultyLabels[state.difficulty]} · ${genreLabels[genre]}`;
  $("#game").dataset.genre=genre;screen.dataset.genre=genre;
  resetLives(true);showView("game");switchMusic(genre);sound("start");setTimeout(nextQuestion,250);
}

function pick(arr){return arr[Math.floor(Math.random()*arr.length)]}
function shuffle(arr){for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]]}return arr}
function uniq(arr){return [...new Set(arr)]}
function questionSignature(text){return String(text||"").trim().toLocaleLowerCase("cs-CZ").replace(/\s+/g," ")}
function distract(values,correct,count=3){return shuffle(uniq(values.filter(v=>String(v)!==String(correct)))).slice(0,count)}
function era(y){if(y<1960)return"Zlatá éra";if(y<1980)return"1960–1979";if(y<2000)return"1980–1999";if(y<2010)return"2000s";if(y<2020)return"2010s";return"2020s"}

function genrePool(genre){
  if(genre==="scifi")return MOVIES.filter(m=>m.genre==="Sci-fi");
  if(genre==="horror")return MOVIES.filter(m=>m.genre==="Horor");
  if(genre==="crime")return MOVIES.filter(m=>m.genre==="Krimi"||m.genre==="Thriller");
  if(genre==="animation")return MOVIES.filter(m=>m.animated||m.genre==="Animovaný");
  if(genre==="comedy")return MOVIES.filter(m=>m.genre==="Komedie");
  if(genre==="fantasy")return MOVIES.filter(m=>m.genre==="Fantasy");
  return MOVIES.filter(m=>m.genre==="Komedie");
}
function difficultyPool(genre=state.genre){
  const base=genrePool(genre);
  if(state.difficulty!=="easy")return base.length>=4?base:MOVIES;
  const famous=base.filter(m=>EASY_TITLES.has(m.title));
  return famous.length>=6?famous:base;
}
function activePool(){const p=difficultyPool(state.genre);return p.length>=4?p:MOVIES}
function weightedMovie(genre){
  const focused=difficultyPool(genre);
  return pick(genre!=="all"&&focused.length?focused:(state.difficulty==="easy"?MOVIES.filter(m=>EASY_TITLES.has(m.title)):MOVIES));
}
function weightedMovieForType(genre,type){
  let pool=difficultyPool(genre);
  if(state.difficulty==="easy"&&(type==="star"||type==="reverseStar")){
    const known=pool.filter(m=>EASY_STAR_TITLES.has(m.title));if(known.length>=4)pool=known;
  }
  if(state.difficulty==="easy"&&(type==="director"||type==="reverseDirector")){
    const known=pool.filter(m=>EASY_DIRECTOR_TITLES.has(m.title));if(known.length>=4)pool=known;
  }
  return pick(pool);
}
function chooseType(){
  if(state.difficulty==="easy"){
    if(state.genre==="animation")return pick(["quote","plot","fact","quote","plot","decade","director","reverseDirector","star"]);
    return pick(["quote","plot","fact","quote","plot","fact","star","decade","director","reverseDirector","reverseStar"]);
  }
  if(state.difficulty==="hard")return pick(["quote","plot","fact","reverseDirector","reverseStar","oldest","newest","year","director","reverseYear","plot","fact"]);
  return pick(["quote","plot","fact","quote","plot","fact","director","star","year","reverseDirector","reverseStar","oldest","newest","reverseYear"]);
}
function personDistractors(field,m){
  let source=activePool();
  if(state.difficulty==="hard"){
    const close=source.filter(x=>x.title!==m.title&&(x.genre===m.genre||Math.abs(x.year-m.year)<=8));
    if(close.length>=4)source=close;
  }else if(state.difficulty==="easy"){
    const far=source.filter(x=>x.title!==m.title&&Math.abs(x.year-m.year)>8);
    if(far.length>=4)source=far;
  }
  let out=distract(source.map(x=>x[field]),m[field]);
  if(out.length<3)out=distract([...source,...MOVIES].map(x=>x[field]),m[field]);
  return out;
}
function yearDistractors(m){
  const years=uniq(activePool().map(x=>x.year));
  if(state.difficulty==="hard"){
    const close=years.filter(y=>y!==m.year&&Math.abs(y-m.year)<=6);
    if(close.length>=3)return shuffle(close).slice(0,3).map(String);
  }
  if(state.difficulty==="easy"){
    const far=years.filter(y=>Math.abs(y-m.year)>=10);
    if(far.length>=3)return shuffle(far).slice(0,3).map(String);
  }
  let out=distract(years,String(m.year)).map(String);
  if(out.length<3)out=distract(MOVIES.map(x=>x.year),String(m.year)).map(String);
  return out;
}
function titleDistractors(m,mode="general"){
  let source=activePool().filter(x=>x.title!==m.title);
  if(mode==="director")source=source.filter(x=>x.director!==m.director);
  if(mode==="star")source=source.filter(x=>x.star!==m.star);
  if(mode==="year")source=source.filter(x=>x.year!==m.year);
  if(state.difficulty==="hard"){
    const close=source.filter(x=>Math.abs(x.year-m.year)<=10);
    if(close.length>=3)source=close;
  }
  let out=shuffle(source).slice(0,3).map(x=>x.title);
  if(out.length<3)out=distract(MOVIES.filter(x=>x.title!==m.title).map(x=>x.title),m.title);
  return out;
}


